package com.rpsbattle.tournament;
import com.rpsbattle.tournament.domain.*;
import com.rpsbattle.tournament.scheduler.*;
import com.rpsbattle.tournament.persistence.*;
import org.junit.jupiter.api.Test;
import java.time.Instant;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class MultistageQualificationTest {
 Tournament cup(int n,List<GroupRoundPlan> plans,int bestOf){var t=new Tournament(UUID.randomUUID().toString(),"Stages",TournamentFormat.GROUP_KNOCKOUT,Instant.EPOCH);t.groupPlans=plans;t.bestOf=bestOf;t.status=TournamentStatus.RUNNING;for(int i=0;i<n;i++)t.participants.add(new TournamentParticipant(UUID.randomUUID().toString(),null,"","P"+i,i));t.matches.addAll(new GroupKnockoutScheduler().schedule(t));return t;}
 void finishPending(Tournament t){for(var m:t.matches)if(m.status==TournamentMatch.Status.PENDING)TournamentFixtures.finish(m,m.participantA.participantId(),4,1);}
 @Test void configurableThreeGroupsTopOneBuildsRealKnockoutWithBye(){var t=cup(9,List.of(new GroupRoundPlan(3,1)),1);assertThat(t.groupStage.groups()).hasSize(3);assertThat(t.matches).hasSize(9);finishPending(t);assertThat(GroupKnockoutScheduler.qualify(t)).isTrue();assertThat(t.groupStage.qualifiers()).hasSize(3);assertThat(t.bracket.stream().filter(n->"BYE".equals(n.resolution()))).hasSize(1);assertThat(t.matches.stream().map(m->m.id).distinct().count()).isEqualTo(t.matches.size());}
 @Test void threeQualificationStagesKeepIndependentStandingsIdsAndFrozenSnapshots(){var plans=List.of(new GroupRoundPlan(4,4),new GroupRoundPlan(2,4),new GroupRoundPlan(2,2));var t=cup(32,plans,3);int guard=0;while(!GroupKnockoutScheduler.complete(t)&&guard++<30){finishPending(t);TournamentSeries.advance(t);GroupKnockoutScheduler.qualify(t);if(GroupKnockoutScheduler.hasKnockout(t))t.matches.addAll(SingleEliminationScheduler.advance(t));}assertThat(GroupKnockoutScheduler.complete(t)).isTrue();assertThat(t.groupHistory).hasSize(2);assertThat(t.stages).hasSize(4);assertThat(t.groupStage.stageNumber()).isEqualTo(3);assertThat(t.groupHistory.get(0).qualifiers()).hasSize(16);assertThat(t.groupHistory.get(1).qualifiers()).hasSize(8);assertThat(t.groupStage.qualifiers()).hasSize(4);for(var m:t.matches){int stage=GroupKnockoutScheduler.stage(t,m.round);assertThat(stage).isBetween(1,4);if(stage<4)assertThat(GroupKnockoutScheduler.group(t,m)).isNotNull();}var oldRows=GroupKnockoutScheduler.view(t).stream().filter(r->r.get("stageNumber").equals(1)).toList();var converter=new TournamentDetailsConverter();var snapshot=converter.convertToEntityAttribute(converter.convertToDatabaseColumn(TournamentDetails.snapshot(t)));var restored=new Tournament(t.id,t.name,t.format,t.createdAt);restored.participants.addAll(t.participants);t.matches.forEach(m->restored.matches.add(m.copy()));snapshot.restore(restored);restored.status=t.status;assertThat(restored.groupPlans).isEqualTo(plans);assertThat(restored.groupHistory).isEqualTo(t.groupHistory);assertThat(GroupKnockoutScheduler.view(restored).stream().filter(r->r.get("stageNumber").equals(1)).toList()).isEqualTo(oldRows);int size=t.matches.size();assertThat(GroupKnockoutScheduler.qualify(t)).isFalse();assertThat(t.matches).hasSize(size);}
 @Test void disqualifiedRosterCannotCreateFakeGamesOrAnInfiniteStageLoop(){var t=cup(8,List.of(new GroupRoundPlan(2,2),new GroupRoundPlan(1,2)),1);for(var p:t.participants)t.operations=t.operations.participant(p.participantId(),ParticipantStatus.DISQUALIFIED);TournamentAdministrationService.settleForfeits(t);assertThat(GroupKnockoutScheduler.qualify(t)).isTrue();assertThat(GroupKnockoutScheduler.qualify(t)).isTrue();assertThat(GroupKnockoutScheduler.complete(t)).isTrue();assertThat(t.bracket.getLast().winnerParticipantId()).isNull();}
 @Test void configurationValidatesCapacityAndLocksBeforeRegistration(){var f=new TeamTournamentTest();var t=f.registry.create("Plan",TournamentFormat.GROUP_KNOCKOUT);t.ownerUserId=f.a.id().value();t.maxParticipants=16;var plan=List.of(new GroupRoundPlan(4,2),new GroupRoundPlan(2,1));f.owned.stagePlan(f.aa,t.id,t.revision,plan);assertThat(t.groupPlans).isEqualTo(plan);assertThatThrownBy(()->f.owned.stagePlan(f.bb,t.id,t.revision,plan)).hasMessage("TOURNAMENT_FORBIDDEN");t.status=TournamentStatus.REGISTRATION;assertThatThrownBy(()->f.owned.stagePlan(f.aa,t.id,t.revision,plan)).hasMessage("TOURNAMENT_LOCKED");for(var invalid:List.of(List.of(new GroupRoundPlan(0,2)),List.of(new GroupRoundPlan(16,3)),List.of(new GroupRoundPlan(2,0))))assertThatThrownBy(()->GroupRoundPlan.validate(invalid,16)).hasMessage("INVALID_STAGE_PLAN");}
}
